DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ambiental_operacion_rango' AND conrelid='base_evaluacion'::regclass) THEN ALTER TABLE base_evaluacion ADD CONSTRAINT ambiental_operacion_rango CHECK (temperatura_operacion_min_c <= temperatura_operacion_max_c); END IF; END $$;
